edits.after:
_keydown(event) {
  if (!([ARROW_LEFT_KEY, ARROW_RIGHT_KEY, ARROW_UP_KEY, ARROW_DOWN_KEY].includes(event.key))) {
    return
  }

  event.stopPropagation()// stopPropagation/preventDefault both added to support up/down keys without scrolling the page
  event.preventDefault()
  const isNext = [ARROW_RIGHT_KEY, ARROW_DOWN_KEY].includes(event.key)
  const children = this._getChildren()
  const enabledChildren = children.filter(child => !isDisabled(child))
  if (enabledChildren.length === 0) {
    return
  }
  let targetIndex = enabledChildren.indexOf(event.target)
  if (targetIndex === -1) {
    targetIndex = 0
  }
  let nextIndex = isNext ? targetIndex + 1 : targetIndex - 1
  if (isNext && nextIndex >= enabledChildren.length) {
    nextIndex = 0
  }
  if (!isNext && nextIndex < 0) {
    nextIndex = enabledChildren.length - 1
  }
  const nextActiveElement = enabledChildren[nextIndex]
  Tab.getOrCreateInstance(nextActiveElement).show()
}
